import { test, expect } from '@playwright/test';

test.describe('Accessibility Error Messages', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should announce error message for required fields', async ({ page }) => {
    await page.getByLabel('Username').fill(''); // Assuming there's a label for the username
    await page.getByRole('button', { name: 'Submit' }).click(); // Assuming there's a submit button

    const errorMessage = await page.getByText('Username is required.'); // Replace with actual error message
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toHaveAttribute('aria-live', 'assertive');
  });

  test('should announce error message for invalid email', async ({ page }) => {
    await page.getByLabel('Email').fill('invalid-email'); // Assuming there's a label for the email
    await page.getByRole('button', { name: 'Submit' }).click(); // Assuming there's a submit button

    const errorMessage = await page.getByText('Please enter a valid email address.'); // Replace with actual error message
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toHaveAttribute('aria-live', 'assertive');
  });
});
